def reimbursable_total(api, trip_id: str) -> dict:
    trip = api.read_trip(trip_id)
    policy = api.read_policy()

    city = trip["city"]
    start = trip["start"]
    end = trip["end"]
    allowance = policy["allowances_usd"][city]
    rates = policy["company_rates_usd_per_unit"][start[:7]]

    month_days = [0, 31, 59, 90, 120, 151, 181, 212, 243, 273, 304, 334]

    def day_number(text):
        y, m, d = [int(p) for p in text.split("-")]
        leap = (y % 4 == 0 and y % 100 != 0) or y % 400 == 0
        prior = y - 1
        number = prior * 365 + prior // 4 - prior // 100 + prior // 400
        number += month_days[m - 1] + d
        if leap and m > 2:
            number += 1
        return number

    nights = day_number(end) - day_number(start)
    if nights < 0:
        nights = 0

    def to_usd(receipt):
        amount = float(receipt["amount"])
        currency = receipt["currency"]
        if currency == "USD":
            rate = 1.0
        else:
            rate = float(rates[currency])
        return round(amount * rate, 2)

    meal_by_day = {}
    hotel_total = 0.0
    taxi_total = 0.0

    for receipt in trip["receipts"]:
        category = receipt["category"]
        note = receipt.get("note", "") or ""
        usd = to_usd(receipt)

        if category == "meal":
            if "alcohol" in note.lower():
                continue
            day = receipt["date"]
            meal_by_day[day] = meal_by_day.get(day, 0.0) + usd
        elif category == "hotel":
            hotel_total += usd
        elif category == "taxi":
            if usd > 40.0 and note.strip() == "":
                continue
            taxi_total += usd

    meal_total = 0.0
    for day in meal_by_day:
        meal_total += min(round(meal_by_day[day], 2), allowance["meals_per_day"])

    hotel_total = min(hotel_total, allowance["hotel_per_night"] * nights)

    total = round(meal_total + hotel_total + taxi_total, 2)
    return {"total_usd": total}
