    def to_usd(receipt):
        currency = receipt["currency"]
        amount = float(receipt["amount"])
        if currency == "USD":
            return amount
        month = receipt["date"][:7]
        return amount * rates[month][currency]

    total = 0.0
    meals_by_day = {}
    hotels_by_day = {}

    for receipt in trip["receipts"]:
        note = receipt.get("note") or ""
        # Alcohol is never reimbursed.
        if "alcohol" in note.lower():
            continue

        usd = to_usd(receipt)
        category = receipt["category"]

        if category == "meal":
            meals_by_day[receipt["date"]] = meals_by_day.get(receipt["date"], 0.0) + usd
        elif category == "hotel":
            hotels_by_day[receipt["date"]] = hotels_by_day.get(receipt["date"], 0.0) + usd
        elif category == "taxi":
            # Taxis over 40 USD need a note explaining why.
            if usd > 40 and note.strip() == "":
                continue
            total += usd
        else:
            total += usd

    # Meals are capped per calendar day.
    for day in meals_by_day:
        total += min(meals_by_day[day], float(allowances["meals_per_day"]))

    # Hotels are capped per night.
    for day in hotels_by_day:
        total += min(hotels_by_day[day], float(allowances["hotel_per_night"]))

    return {"total_usd": round(total, 2)}
